    make(2, "小球以固定速率繞圓運動。下列敘述何者正確？", {"A": "速率固定所以速度與加速度都為零", "B": "速度方向持續改變，因此仍有指向圓心的加速度", "C": "加速度一定沿切線方向且背離圓心", "D": "只有速率增加才會有加速度"}, "B", "速率是速度大小；即使速率固定，速度方向仍持續改變，因此有指向圓心的向心加速度。", "先區分速率與速度，再檢查速度的大小或方向是否改變。", ["確認題目只說速率固定，不代表速度向量固定。", "觀察圓周各點的切線方向持續改變。", "速度方向改變表示有加速度。", "等速率圓周運動的加速度指向圓心。", "所以選 B。"], "easy"),
    make(3, "物體以速率 4 m/s 沿半徑 2 m 的圓周運動。其向心加速度大小為何？", {"A": "0.5 m/s²", "B": "2 m/s²", "C": "8 m/s²", "D": "16 m/s²"}, "C", "向心加速度 a_c＝v²/r＝4²÷2＝16÷2＝8 m/s²。", "先平方速率，再除以半徑，最後檢查單位與方向指向圓心。", ["列出速率 v＝4 m/s。", "列出半徑 r＝2 m。", "寫出 a_c＝v²/r。", "計算 4²÷2＝8 m/s²。", "所以選 C。"], "medium"),
    make(4, "若圓周運動半徑不變，速率由 v 增加為 2v，所需向心加速度如何變化？", {"A": "變為原來 1/4", "B": "變為原來 1/2", "C": "變為原來 2 倍", "D": "變為原來 4 倍"}, "D", "a_c＝v²/r；半徑固定而速率加倍時，v² 變為 4 倍，所以向心加速度變為 4 倍。", "使用比例關係時先看公式中的平方次方，不只做一次倍乘。", ["寫出原本 a_c＝v²/r。", "將速率換成 2v。", "新加速度為 (2v)²/r＝4v²/r。", "與原式相比是 4 倍。", "所以選 D。"], "medium"),
    make(5, "若物體速率固定，圓周半徑由 r 變為 2r，向心加速度如何變化？", {"A": "變為原來 1/2", "B": "變為原來 2 倍", "C": "變為原來 4 倍", "D": "不變"}, "A", "a_c＝v²/r；速率固定、半徑加倍時，分母加倍，向心加速度變為原來一半。", "固定 v 後只比較半徑在分母中的比例。", ["確認速率 v 不變。", "原本加速度為 v²/r。", "新半徑為 2r，所以新加速度為 v²/(2r)。", "這是原來的 1/2。", "所以選 A。"], "easy"),
