    make(8, "繩球在水平面上繞圓運動時繩子突然斷裂。忽略空氣阻力，球最初會沿哪個方向運動？", {"A": "立刻向圓心飛去", "B": "沿斷裂瞬間位置的切線方向前進", "C": "沿半徑向外直線前進", "D": "立即停在原地"}, "B", "繩張力消失後不再有維持圓周的向心合力；球保留斷裂瞬間的切線速度，因此沿切線方向離開。", "把斷裂前的瞬時速度方向與斷裂後的受力變化分開判斷。", ["找出斷裂瞬間球的切線方向。", "確認繩張力消失，圓心方向合力不再維持。", "物體仍保有原來的瞬時速度。", "因此初始路徑沿切線，不是向外半徑。", "所以選 B。"], "easy"),
    make(9, "人造衛星繞地球近似圓周運動時，若忽略其他影響，維持其繞行的向心力主要來自何者？", {"A": "地球引力", "B": "衛星向外噴出的力", "C": "太陽能板的支持力", "D": "沒有任何力，因為衛星速率可固定"}, "A", "地球引力指向地心，提供衛星圓周運動所需的向心合力；速率固定不代表沒有加速度或受力。", "把向心力視為需求，再判斷哪個實際交互作用方向指向地心。", ["確認衛星圓周路徑的圓心接近地球中心。", "列出地球對衛星的萬有引力。", "引力方向指向地球中心。", "因此它提供向心合力。", "所以選 A。"], "medium"),
    make(10, "質量 2 kg 的物體以 6 m/s 速率沿半徑 3 m 圓周運動。維持此運動所需的向心力大小為何？", {"A": "4 N", "B": "12 N", "C": "24 N", "D": "36 N"}, "C", "F_c＝ma_c＝m v²/r＝2×36÷3＝24 N。", "先用 v²/r 求向心加速度，再乘以質量求向心力。", ["列出 m＝2 kg、v＝6 m/s、r＝3 m。", "計算 a_c＝6²÷3＝12 m/s²。", "使用 F＝ma。", "計算 2×12＝24 N。", "所以選 C。"], "hard"),
